import ctypes
from ctypes import c_double
class GSLFunction:
    def __init__(self, func):
        self.func = func
        self.c_func = ctypes.CFUNCTYPE(c_double, c_double)(self.wrapper)
    def wrapper(self, x):
        return self.func(x)
class CQuadWorkspace:
    def __init__(self, size):
        self.size = size
        self.workspace = gsl.gsl_integration_cquad_workspace_alloc(size)
    def free(self):
        gsl.gsl_integration_cquad_workspace_free(self.workspace)
def integrate_function(func, a, b, epsabs, epsrel, workspace_size):
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    global gsl
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    gsl.gsl_integration_cquad.argtypes = [ctypes.c_void_p, c_double, c_double, c_double, c_double, ctypes.c_void_p, ctypes.POINTER(c_double), ctypes.POINTER(c_double), ctypes.POINTER(ctypes.c_size_t)]
    gsl.gsl_integration_cquad.restype = c_double
    f = GSLFunction(func)
    workspace = CQuadWorkspace(workspace_size)
    result = c_double()
    abserr = c_double()
    neval = ctypes.c_size_t()
    status = gsl.gsl_integration_cquad(f.c_func, a, b, epsabs, epsrel, workspace.workspace, ctypes.byref(result), ctypes.byref(abserr), ctypes.byref(neval))
    workspace.free()
    if status != 0:
        raise RuntimeError(f"Integration failed with status {status}")
    return result.value, abserr.value, neval.value
