class GslChebSeries:
    def __init__(self, coeffs, a, b, order):
        self.coeffs = (c_double * len(coeffs))(*coeffs)
        self.a = c_double(a)
        self.b = c_double(b)
        self.order = c_int(order)
        self.derived_coeffs = (c_double * order)()
        self.status = gsl.gsl_cheb_init(self.coeffs, self.order.value)
        if self.status != 0:
            raise Exception("Failed to initialize Chebyshev series")

    def chebyshev_derivative(self):
        status = gsl.gsl_cheb_calc_deriv(self.coeffs, self.a, self.b, self.order, self.derived_coeffs)
        if status != 0:
            raise Exception("Failed to calculate derivative")
        return list(self.derived_coeffs)

def chebyshev_derivative(coeffs, a, b, order):
    series = GslChebSeries(coeffs, a, b, order)
    return series.chebyshev_derivative()

