def compute_skewness(data, stride, n):
    if not isinstance(data, np.ndarray) or data.dtype != np.float64:
        raise ValueError("Data must be a NumPy array of dtype float64.")
    if stride <= 0 or n <= 0:
        raise ValueError("Stride and n must be positive integers.")
    if len(data) < n * stride:
        raise ValueError("Data array is too short for the given stride and n.")
    data_ptr = data.ctypes.data_as(ctypes.POINTER(ctypes.c_double))
    return gsl.gsl_stats_skew(data_ptr, stride, n)

