gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class gsl_function(ctypes.Structure):
    _fields_ = [("function", ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)),
                ("params", ctypes.c_void_p)]

class gsl_integration_qaws_table(ctypes.Structure):
    pass

class gsl_integration_workspace(ctypes.Structure):
    pass

def create_workspace(limit):
    func = gsl.gsl_integration_workspace_alloc
    func.restype = ctypes.POINTER(gsl_integration_workspace)
    func.argtypes = [ctypes.c_size_t]
    return func(limit)

def create_qaws_table():
    func = gsl.gsl_integration_qaws_table_alloc
    func.restype = ctypes.POINTER(gsl_integration_qaws_table)
    func.argtypes = [ctypes.c_double, ctypes.c_double, ctypes.c_int, ctypes.c_int]
    return func(0, 0, 0, 0)

def free_workspace(workspace):
    func = gsl.gsl_integration_workspace_free
    func.argtypes = [ctypes.POINTER(gsl_integration_workspace)]
    func(workspace)

def free_qaws_table(table):
    func = gsl.gsl_integration_qaws_table_free
    func.argtypes = [ctypes.POINTER(gsl_integration_qaws_table)]
    func(table)

def gsl_integration_qaws(f, a, b, table, epsabs, epsrel, limit, workspace):
    func = gsl.gsl_integration_qaws
    func.restype = ctypes.c_int
    func.argtypes = [ctypes.POINTER(gsl_function), ctypes.c_double, ctypes.c_double,
                     ctypes.POINTER(gsl_integration_qaws_table), ctypes.c_double, ctypes.c_double,
                     ctypes.c_size_t, ctypes.POINTER(gsl_integration_workspace),
                     ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]
    result = ctypes.c_double()
    abserr = ctypes.c_double()
