import json
class GSLFunction:
    def __init__(self, func):
        self.func = func
        self.c_func = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_void_p))(self.wrapper)

    def wrapper(self, x, params):
        return self.func(x)

def compute_integration(m, n):
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    def f(x, params):
        return x**m

    gsl_function = GSLFunction(f)

    workspace = gsl.gsl_integration_workspace_alloc(n)
    result = ctypes.c_double()
    abserr = ctypes.c_double()

    gsl.gsl_integration_qng(gsl_function.c_func, 0, 1, 1e-8, 1e-8, ctypes.byref(result), ctypes.byref(abserr), workspace)

    gsl.gsl_integration_workspace_free(workspace)

    expected_result = 1 / (m + 1) if m != -1 else float('inf')

    return json.dumps({"computed_result": result.value, "expected_result": expected_result})

