    return gsl_vector(size, 1, data, None, 1)

def hesstri_decomp(A, B, U=None, V=None, work=None):
    A_gsl = numpy_to_gsl_matrix(A)
    B_gsl = numpy_to_gsl_matrix(B)
    U_gsl = numpy_to_gsl_matrix(U) if U is not None else None
    V_gsl = numpy_to_gsl_matrix(V) if V is not None else None
    work_gsl = numpy_to_gsl_vector(work) if work is not None else None

    gsl.gsl_linalg_hesstri_decomp.argtypes = [ctypes.POINTER(gsl_matrix), ctypes.POINTER(gsl_matrix), ctypes.POINTER(gsl_matrix), ctypes.POINTER(gsl_matrix), ctypes.POINTER(gsl_vector)]
    gsl.gsl_linalg_hesstri_decomp.restype = ctypes.c_int

    result = gsl.gsl_linalg_hesstri_decomp(ctypes.byref(A_gsl), ctypes.byref(B_gsl), ctypes.byref(U_gsl) if U_gsl else None, ctypes.byref(V_gsl) if V_gsl else None, ctypes.byref(work_gsl) if work_gsl else None)

    if result != 0:
        raise RuntimeError(f"Hessenberg-triangular decomposition failed with error code {result}.")

    return A, B, U, V

