class gsl_matrix(ctypes.Structure):
    _fields_ = [("size1", ctypes.c_size_t), ("size2", ctypes.c_size_t), ("tda", ctypes.c_size_t), ("data", ctypes.POINTER(ctypes.c_double)), ("block", ctypes.c_void_p), ("owner", ctypes.c_int)]

class gsl_vector(ctypes.Structure):
    _fields_ = [("size", ctypes.c_size_t), ("stride", ctypes.c_size_t), ("data", ctypes.POINTER(ctypes.c_double)), ("block", ctypes.c_void_p), ("owner", ctypes.c_int)]

def numpy_to_gsl_matrix(np_array):
    if len(np_array.shape) != 2 or np_array.shape[0] != np_array.shape[1]:
        raise ValueError("Input array must be a square matrix.")
    size = np_array.shape[0]
    data = np_array.ctypes.data_as(ctypes.POINTER(ctypes.c_double))
    return gsl_matrix(size, size, size, data, None, 1)

def numpy_to_gsl_vector(np_array):
    if len(np_array.shape) != 1:
        raise ValueError("Input array must be a vector.")
    size = np_array.shape[0]
    data = np_array.ctypes.data_as(ctypes.POINTER(ctypes.c_double))
    return gsl_vector(size, 1, data, None, 1)

def hesstri_decomp(A, B, U, V, work):
    A_gsl = numpy_to_gsl_matrix(A)
    B_gsl = numpy_to_gsl_matrix(B)
    U_gsl = numpy_to_gsl_matrix(U) if U is not None else None
    V_gsl = numpy_to_gsl_matrix(V) if V is not None else None
    work_gsl = numpy_to_gsl_vector(work)

    gsl.gsl_linalg_hesstri_decomp.argtypes = [ctypes.POINTER(gsl_matrix), ctypes.POINTER(gsl_matrix), ctypes.POINTER(gsl_matrix), ctypes.POINTER(gsl_matrix), ctypes.POINTER(gsl_vector)]
    gsl.gsl_linalg_hesstri_decomp.restype = ctypes.c_int

    result = gsl.gsl_linalg_hesstri_decomp(A_gsl, B_gsl, U_gsl, V_gsl, work_gsl)
    if result != 0:
        raise RuntimeError(f"Hessenberg-triangular decomposition failed with error code {result}.")

    return A, B, U, V

