    try:
        assert abs(scaled_enorm([1, 2, 3], [4, 5, 6]) - 32) < 1e-9
        assert abs(scaled_enorm([0, 0, 0], [1, 2, 3]) - 0) < 1e-9
        assert abs(scaled_enorm([1, 1, 1], [1, 1, 1]) - 3) < 1e-9
