import ctypes
from ctypes import c_double

gsl_cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class GSLFunction(ctypes.Structure):
    _fields_ = [("function", ctypes.CFUNCTYPE(c_double, c_double, ctypes.c_void_p)),
                ("params", ctypes.c_void_p)]

class GSLMinFMinimizer(ctypes.Structure):
    pass

class GSLMinFMinimizerType(ctypes.Structure):
    pass

def quad_golden_iterate_wrapper(minimizer):
    return gsl.gsl_min_fminimizer_iterate(minimizer)

def quad_golden_init_wrapper(type, f, x_minimum, x_lower, x_upper, minimizer):
    return gsl.gsl_min_fminimizer_set(type, f, x_minimum, x_lower, x_upper, minimizer)

def create_gsl_function(py_func):
    def wrapper(x, params):
        return py_func(x)
    return GSLFunction(function=ctypes.CFUNCTYPE(c_double, c_double, ctypes.c_void_p)(wrapper), params=None)

def main(f, x_minimum, f_minimum, x_lower, f_lower, x_upper, f_upper):
    type = gsl.gsl_min_fminimizer_quad_golden
    minimizer = gsl.gsl_min_fminimizer_alloc(type)
    func = create_gsl_function(f)
    status = quad_golden_init_wrapper(type, ctypes.byref(func), x_minimum, x_lower, x_upper, minimizer)
    if status != 0:
        raise Exception("Initialization failed")
    status = quad_golden_iterate_wrapper(minimizer)
    if status != 0:
        raise Exception("Iteration failed")
    x_minimum = minimizer.contents.x_minimum
    f_minimum = minimizer.contents.f_minimum
    x_lower = minimizer.contents.x_lower
    f_lower = minimizer.contents.f_lower
    x_upper = minimizer.contents.x_upper
    f_upper = minimizer.contents.f_upper
    gsl.gsl_min_fminimizer_free(minimizer)
    return x_minimum, f_minimum, x_lower, f_lower, x_upper, f_upper

def test():
    def f(x):
        return (x - 3) ** 2 + 4
    x_minimum, f_minimum, x_lower, f_lower, x_upper, f_upper = main(f, 0, f(0), -10, f(-10), 10, f(10))
    assert round(x_minimum, 5) == 3.0, f"Expected 3.0, got {x_minimum}"
    assert round(f_minimum, 5) == 4.0, f"Expected 4.0, got {f_minimum}"
    assert x_lower < x_minimum < x_upper, f"Bounds incorrect: {x_lower}, {x_minimum}, {x_upper}"
    print("Test passed")

test()

