    rows = len(matrix)
    cols = len(matrix[0]) if rows > 0 else 0
    if any(len(row) != cols for row in matrix):
        raise ValueError('Input matrix is not square or has inconsistent row lengths.')
    gsl_matrix = GSLMatrix(rows, cols)
    for i in range(rows):
        for j in range(cols):
            gsl.gsl_matrix_set(gsl_matrix.gsl_matrix_p, i, j, matrix[i][j])
    return gsl_matrix

