    rows = gsl_matrix.rows
    cols = gsl_matrix.cols
    result = np.zeros((rows, cols))
    for i in range(rows):
        for j in range(cols):
            result[i][j] = gsl.gsl_matrix_get(gsl_matrix.gsl_matrix_p, i, j)
    return result

def compute_matrix_exponential(matrix, mode):
    if mode not in [0, 1]:
        raise ValueError('Mode must be 0 or 1.')
    gsl_matrix = matrix_to_gsl(matrix)
    exp_gsl_matrix = GSLMatrix(gsl_matrix.rows, gsl_matrix.cols)
