    def __init__(self):
        self.matrix = gsl.gsl_spmatrix_alloc(10, 10)
    def set_element(self, row, col, value):
        gsl.gsl_spmatrix_set(self.matrix, row, col, value)
    def get_elements(self):
        elements = []
        for i in range(10):
            for j in range(10):
                val = gsl.gsl_spmatrix_get(self.matrix, i, j)
                if val != 0:
                    elements.append((i, j, val))
        return elements
    def swap_elements(self, i, j):
        # Assuming i and j are indices into a flattened version of the matrix
        row1, col1 = divmod(i, 10)
        row2, col2 = divmod(j, 10)
        temp = gsl.gsl_spmatrix_get(self.matrix, row1, col1)
        gsl.gsl_spmatrix_set(self.matrix, row1, col1, gsl.gsl_spmatrix_get(self.matrix, row2, col2))
        gsl.gsl_spmatrix_set(self.matrix, row2, col2, temp)
