    _fields_ = [('size1', ctypes.c_size_t), ('size2', ctypes.c_size_t), ('tda', ctypes.c_size_t), ('data', ctypes.POINTER(gsl_complex)), ('block', ctypes.c_void_p), ('owner', ctypes.c_int)]

