def convert_gsl_matrix_complex_to_list(matrix):
    size = matrix.size1
    result = []
    for i in range(size):
        row = []
        for j in range(size):
            real = matrix.data[i * size + j].dat[0]
            imag = matrix.data[i * size + j].dat[1]
            row.append((real, imag))
        result.append(row)
    return result

