import ctypes
import numpy as np
class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.matrix = None
        self._allocate()
    def _allocate(self):
        self.matrix = gsl.gsl_matrix_alloc(self.rows, self.cols)
    def free(self):
        gsl.gsl_matrix_free(self.matrix)
    def to_numpy(self):
        data = (ctypes.c_double * (self.rows * self.cols)).from_address(ctypes.addressof(self.matrix.contents.data))
        return np.ctypeslib.as_array(data).reshape(self.rows, self.cols)
def list_to_ctypes_matrix(lst):
    rows = len(lst)
    cols = len(lst[0]) if lst else 0
    matrix = GSLMatrix(rows, cols)
    for i in range(rows):
        for j in range(cols):
            gsl.gsl_matrix_set(matrix.matrix, i, j, lst[i][j])
    return matrix
def compute_covariance(jacobian, epsrel):
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    global gsl
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    jacobian_matrix = list_to_ctypes_matrix(jacobian)
    covar_matrix = GSLMatrix(jacobian_matrix.rows, jacobian_matrix.cols)
    gsl.gsl_multifit_nlinear_covar.argtypes = [ctypes.POINTER(gsl.gsl_matrix), ctypes.c_double, ctypes.POINTER(gsl.gsl_matrix)]
    gsl.gsl_multifit_nlinear_covar.restype = ctypes.c_int
    result = gsl.gsl_multifit_nlinear_covar(jacobian_matrix.matrix, epsrel, covar_matrix.matrix)
    if result != 0:
        raise Exception(f"Error computing covariance matrix: {result}")
    covar_np = covar_matrix.to_numpy()
    jacobian_matrix.free()
    covar_matrix.free()
    return covar_np.tolist()

