import numpy as np
def chebyshev_coefficients(order, func, a, b):
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    class gsl_function(ctypes.Structure):
        _fields_ = [("function", ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)),
                    ("params", ctypes.c_void_p)]

    class gsl_cheb_series(ctypes.Structure):
        _fields_ = [("order", ctypes.c_size_t),
                    ("a", ctypes.c_double),
                    ("b", ctypes.c_double),
                    ("c", ctypes.POINTER(ctypes.c_double))]

    def func_wrapper(x, params):
        return func(x)

    c_func = gsl_function(func_wrapper, None)
    c_func.function.restype = ctypes.c_double
    c_func.function.argtypes = [ctypes.c_double, ctypes.c_void_p]

    cheb_series = gsl_cheb_series()
    cheb_series.order = order
    cheb_series.a = a
    cheb_series.b = b
    cheb_series.c = (ctypes.c_double * (order + 1))()

    gsl.gsl_cheb_init.argtypes = [ctypes.POINTER(gsl_cheb_series), ctypes.POINTER(gsl_function)]
    gsl.gsl_cheb_init(ctypes.byref(cheb_series), ctypes.byref(c_func))

    coefficients = [cheb_series.c[i] for i in range(order + 1)]
    return coefficients
