class GSLRNG:
    def __init__(self, seed):
        self.rng_type = gsl.gsl_rng_default
        self.rng = gsl.gsl_rng_alloc(self.rng_type)
        gsl.gsl_rng_set(self.rng, seed)

    def __del__(self):
        gsl.gsl_rng_free(self.rng)

    def hypergeometric(self, n1, n2, t):
        return gsl.gsl_ran_hypergeometric(self.rng, n1, n2, t)

def hypergeometric_pdf(k, n1, n2, t):
    return gsl.gsl_ran_hypergeometric_pdf(k, n1, n2, t)

def assert_test():
    rng = GSLRNG(42)
    n1, n2, t, k = 10, 20, 5, 2
    random_number = rng.hypergeometric(n1, n2, t)
    pdf_value = hypergeometric_pdf(k, n1, n2, t)
    assert 0 <= random_number <= min(t, n1), "Random number out of expected range"
    assert 0 <= pdf_value <= 1, "PDF value out of expected range"
    print(f"Random Number: {random_number}, PDF Value: {pdf_value}")

if __name__ == "__main__":
    assert_test()

