from ctypes import c_double, c_size_t, POINTER

gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class gsl_function(ctypes.Structure):
    _fields_ = [("function", ctypes.CFUNCTYPE(c_double, c_double, POINTER(c_double))),
                ("params", POINTER(c_double))]

def func_wrapper(x, params):
    return py_func(x)

def compute_integral(py_func, a, b, epsabs, epsrel, n):
    global func
    func = gsl_function()
    func.function = ctypes.CFUNCTYPE(c_double, c_double, POINTER(c_double))(func_wrapper)
    func.params = None

    workspace = gsl.gsl_integration_romberg_alloc(n)
    result = c_double(0)
    neval = c_size_t(0)

    gsl.gsl_integration_romberg.restype = c_int
    gsl.gsl_integration_romberg.argtypes = [POINTER(gsl_function), c_double, c_double, c_double, c_double, POINTER(c_double), POINTER(c_size_t)]
    status = gsl.gsl_integration_romberg(ctypes.byref(func), a, b, epsabs, epsrel, ctypes.byref(result), ctypes.byref(neval))

    gsl.gsl_integration_romberg_free(workspace)

    if status != 0:
        raise RuntimeError(f"Integration failed with status {status}")

    return {"integral": result.value, "neval": neval.value}

