def cblas_daxpy(N, alpha, X, Y):
    if len(X) != len(Y) or N > len(X):
        raise ValueError("Invalid input lengths or N value")
    c_N = ctypes.c_int(N)
    c_alpha = ctypes.c_double(alpha)
    c_X = (ctypes.c_double * N)(*X)
    c_Y = (ctypes.c_double * N)(*Y)
    c_incX = ctypes.c_int(1)
    c_incY = ctypes.c_int(1)
    try:
        gsl.cblas_daxpy(c_N, c_alpha, c_X, c_incX, c_Y, c_incY)
    except Exception as e:
        return {"error": str(e)}
    return list(c_Y)

